let inventorySelected='';let searchAll='';let lang=localStorage.getItem('sial-lang')||'en',view='control',user=null,data={},report={},ops={},statusOptions={po:[],invoice:[]},selectedPO=null,regionFilter='',poFilter='outstanding',previewState=null,users=[],asnAssignments=[],selectedIds=new Set(),backups=[],poSearch='',warehouseAssignments=[];
const can=p=>!!user?.is_admin||!!user?.permissions?.includes(p);const tr=k=>(lang==='ar'?AR:EN)[k]||k,st=k=>(lang==='ar'?STATUS_AR:STATUS_EN)[k]||String(k||'—').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n||0).toLocaleString(lang==='ar'?'ar-SA':'en-US'),money=n=>Number(n||0).toLocaleString(lang==='ar'?'ar-SA':'en-US',{maximumFractionDigits:2,minimumFractionDigits:2});
function toast(message){let x=document.getElementById('toast');x.textContent=message;x.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>x.style.display='none',5000)}
function detailError(j){if(typeof j.detail==='string')return j.detail;if(j.detail?.message)return `${j.detail.message} (PO ${j.detail.po_number})`;return JSON.stringify(j.detail||j)}
async function api(url,method='GET',body){const options={method,headers:{'X-Logistics-Request':'1'}};if(body!==undefined){if(body instanceof FormData)options.body=body;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}}const r=await fetch('/api/'+url,options);const j=await r.json().catch(()=>({detail:'Request failed'}));if(!r.ok){let e=new Error(detailError(j));e.detail=j.detail;throw e}return j}
function field(name,label,type='text',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" ${extra}></label>`}function select(name,label,options,extra=''){return `<label>${esc(label)}<select name="${name}" ${extra}>${options}</select></label>`}function choices(values,selected){return values.map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`).join('')}function table(head,records){return records.length?`<div class="table-wrap"><table><thead><tr>${head.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${records.join('')}</tbody></table></div>`:`<div class="empty">${tr('noRows')}</div>`}
function shell(content,title,subtitle=''){let nav=[['control','control'],['reports','reports'],['search','search'],['ngh','ngh'],['recent','recent'],['open','open'],['inventory','inventory'],['imports','imports'],['tasks','tasks'],['admin','admin']].filter(([key])=>(user?.role==='warehouse'?key==='tasks':key==='control'||key==='admin'||key==='tasks'||key==='recent'||(key==='open'||key==='search'||key==='ngh'?(can('pos_edit')||can('invoice_edit')||can('issue_edit')):can(({inventory:'inventory_edit',reports:'reports_view',imports:'imports_apply',tasks:'task_edit'})[key]))));document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.getElementById('app').innerHTML=`<div class="shell"><header class="top"><div class="brand"><div class="brand-icon">S</div><div><h1>Sial Logistics</h1><small>PO · Inventory · Delivery · build 25 Nov 2026</small></div></div><div class="top-actions"><span class="small">${esc(user?.username||'')}</span><button onclick="toggleLang()">${lang==='en'?'العربية':'English'}</button><button onclick="logout()">${tr('signOut')}</button></div></header><div class="layout"><aside class="side">${nav.map(([key,label])=>`<button class="${view===key?'active':''}" onclick="go('${key}')">${tr(label)}${key==='tasks'&&user?.is_admin&&asnAssignments.some(x=>x.status==='submitted')?` <span class="pill warn">${asnAssignments.filter(x=>x.status==='submitted').length}</span>`:''}</button>`).join('')}</aside><main class="main"><div class="page-title"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div></div>${content}</main></div></div>`}
async function refresh(){try{user=await api('auth/me');data=await api('dashboard');if(user.role==='warehouse'){report={};ops={};statusOptions={po:[],invoice:[]}}else if(user.is_admin||user.permissions.includes('reports_view')){[report,ops,statusOptions]=await Promise.all([api('reports'),api('reports/operations'),api('status-options')])}else{report={};ops={};statusOptions=await api('status-options')}if(user.is_admin)users=await api('auth/users');asnAssignments=user.role==='warehouse'?[]:await api('asn-assignments');warehouseAssignments=await api('warehouse-assignments');if(user.role==='warehouse')view='tasks';else if(!user.is_admin&&view==='admin')view='control';render()}catch(e){if(e.message==='Sign in required')loginView();else toast(e.message)}}function go(x){view=x;selectedPO=null;render();window.scrollTo({top:0,behavior:'instant'})}function render(){if(!user)return loginView();if(view==='control')return controlView();if(view==='search')return allPOView();if(view==='ngh')return specialPOView('ngh');if(view==='recent')return specialPOView('recent');if(view==='open'){poView();showNextNumber();return}if(view==='inventory')return inventoryView();if(view==='reports')return reportView();if(view==='imports')return importsView();if(view==='tasks')return tasksView();return adminView()}
function loginView(reset=false){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.getElementById('app').innerHTML=`<div class="login"><div class="brand" style="justify-content:center;margin-bottom:20px"><div class="brand-icon">S</div><h1>Sial Logistics</h1></div><div class="card"><h3>${reset?tr('forgot'):tr('signIn')}</h3><form class="form one" onsubmit="${reset?'requestReset':'login'}(event)">${reset?field('email','Email','email','required'):field('username',tr('user'),'text','required')+field('password',tr('password'),'password','required')}<button class="primary">${reset?tr('sendReset'):tr('signIn')}</button></form><p><button class="secondary" onclick="loginView(${!reset})">${reset?tr('signIn'):tr('forgot')}</button></p></div></div>`}async function login(e){e.preventDefault();try{await api('auth/login','POST',Object.fromEntries(new FormData(e.target)));await refresh()}catch(x){toast(x.message)}}async function logout(){await api('auth/logout','POST',{});user=null;loginView()}async function requestReset(e){e.preventDefault();try{await api('auth/reset-request','POST',Object.fromEntries(new FormData(e.target)));toast('Check your email for a reset link.')}catch(x){toast(x.message)}}function toggleLang(){lang=lang==='en'?'ar':'en';localStorage.setItem('sial-lang',lang);render()}
Object.assign(EN,{search:'Search all POs',ngh:'NGH POs',recent:'Recently added',total:'Total',rules:'Packing rules'});Object.assign(AR,{search:'بحث في جميع أوامر الشراء',ngh:'أوامر الحرس الوطني',recent:'أوامر مضافة حديثًا',total:'الإجمالي',rules:'قواعد التعبئة'});
function allPOView(){let q=searchAll.toLowerCase(),ps=(data.pos||[]).filter(p=>!q||p.number.toLowerCase().includes(q));shell(`<div class="card"><label>${tr('search')}<input type="search" value="${esc(searchAll)}" oninput="searchAll=this.value;allPOView()" placeholder="PO number"></label></div><div class="po-list">${ps.slice(0,100).map(p=>`<article class="po-row"><div class="po-main"><button class="po-link" onclick="openPO(${p.id})">${esc(p.number)}</button><div>${esc(p.region||'')} · ${st(p.status)}</div></div><div>${fmt(p.delivered_qty||0)} delivered · ${fmt(p.remaining_qty||0)} outstanding</div><button class="secondary" onclick="openPO(${p.id})">${tr('details')}</button></article>`).join('')}</div>`,tr('search'))}
function poAddress(p){return (Number(p.remaining_qty)>0 && p.is_outstanding && p.address_ar) ? p.address_ar : (p.address||p.address_ar||'')}
function specialPOView(which){let ps=(data.pos||[]).filter(p=>which==='ngh'?p.is_ngh:p.added_from_pdf).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));shell(`<div class="po-list">${ps.map(p=>`<article class="po-row"><div><button class="po-link" onclick="openPO(${p.id})">${esc(p.number)}</button><div>${esc(poAddress(p))}</div></div><div>${st(p.status)} · ${esc(p.due_date||'')}</div><button class="secondary" onclick="openPO(${p.id})">${tr('details')}</button></article>`).join('')}</div>`,tr(which))}
function controlView(){
 const pos=(data.pos||[]).filter(p=>p.is_outstanding),urgent=data.urgent||[],reminders=data.reminders||[],submitted=asnAssignments.filter(x=>x.status==='submitted'),warehouse=warehouseAssignments.filter(x=>x.status==='open');
 const stats=`<div class="stats stats-five">${[[tr('outstanding'),pos.length],[tr('urgent'),new Set(urgent.map(x=>x.po_id)).size],[tr('reminders'),new Set(reminders.map(x=>x.po_id)).size],['ASN to review',submitted.length],['Warehouse jobs',warehouse.length]].map(([label,n])=>`<div class="stat"><span>${label}</span><strong>${fmt(n)}</strong></div>`).join('')}</div>`;
 const rows=list=>{let grouped=new Map();for(const x of list){if(!grouped.has(x.po_id))grouped.set(x.po_id,{...x,items:[]});grouped.get(x.po_id).items.push(`${x.item_code}: ${fmt(x.ordered_qty||0)} pcs`)}return [...grouped.values()].slice(0,12).map(x=>`<div class="alert-row"><div><strong>${esc(x.number)}</strong><small>${esc(x.region||'—')} · ${esc(x.items.join(' · '))} · ${esc(x.due_date)}</small></div><button class="secondary" onclick="openPO(${x.po_id})">${tr('details')}</button></div>`).join('')||`<p class="empty">${tr('noRows')}</p>`};
 const regions=[...new Set(pos.map(x=>x.region).filter(Boolean))].sort().map(r=>`<button class="region-card" onclick="regionFilter='${esc(r)}';view='open';selectedPO=null;render()"><strong>${esc(r)}</strong><span>${fmt(pos.filter(x=>x.region===r).length)} POs</span></button>`).join('');
 shell(stats+`<div class="quick-actions"><button class="primary" onclick="view='open';selectedPO=null;render()">${tr('outstandingPOs')}</button><button class="secondary" onclick="go('tasks')">${tr('tasks')}</button><button class="secondary" onclick="go('imports')">${tr('imports')}</button></div><div class="card"><h3>Outstanding by region</h3><div class="regions-grid">${regions||`<p class="empty">Import Due and Region to populate this page.</p>`}</div></div><div class="grid"><div class="card"><h3>🚨 ${tr('urgent')}</h3>${rows(urgent)}</div><div class="card"><h3>${tr('reminders')}</h3>${rows(reminders)}</div></div>`,tr('control'),'Today’s orders and work needing attention.');
}
function openPO(id){selectedPO=Number(id);view='open';render();window.scrollTo({top:0,behavior:'instant'})}
function filteredPOs(){return (data.pos||[]).filter(p=>(!regionFilter||p.region===regionFilter)&&(poFilter==='archive'?p.archived:poFilter==='all'?!p.archived:poFilter==='delivered'?!p.archived&&['delivered','gr_issued'].includes(p.status):!p.archived&&p.is_outstanding)).filter(p=>!poSearch||[p.number,p.region,p.customer,p.customer_po].some(v=>String(v||'').toLowerCase().includes(poSearch.toLowerCase()))).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')||a.number.localeCompare(b.number))}
function togglePOSelection(id,checked){if(checked)selectedIds.add(id);else selectedIds.delete(id);let count=document.getElementById('selection-count');if(count)count.textContent=selectedIds.size}
function toggleAllPOs(checked){for(let p of filteredPOs()){if(checked)selectedIds.add(p.id);else selectedIds.delete(p.id)}render()}
function updatePOSearch(el){let n=el.selectionStart;poSearch=el.value;render();let next=document.querySelector('input[name=search]');if(next){next.focus();next.setSelectionRange(n,n)}}
function poView(){
  const p=(data.pos||[]).find(x=>x.id===selectedPO);
  if(p){shell(`<div class="detail-top"><button class="secondary" onclick="selectedPO=null;render()">← ${tr('outstandingPOs')}</button><span class="pill">${st(p.status)}</span></div><div class="po-focus"><section>${poDetails(p)}</section><aside>${poDocumentPanel(p)}</aside></div>`,`${tr('po')} ${p.number}`,p.region||'');showNextNumber();return}
  const pos=filteredPOs(),regions=[...new Set((data.regional_rows||[]).map(x=>x.region).filter(Boolean))].sort();
  for(const id of [...selectedIds])if(!pos.some(p=>p.id===id))selectedIds.delete(id);
  const filters=`<div class="card compact po-filters">${field('search','Search PO / customer / customer PO','search',`value="${esc(poSearch)}" oninput="updatePOSearch(this)"`)}${select('region',tr('region'),choices([['',tr('allRegions')],...regions.map(x=>[x,x])],regionFilter),'onchange="regionFilter=this.value;selectedIds.clear();render()"')}${select('stage',tr('status'),choices([['outstanding',tr('allOutstanding')],['delivered',st('delivered')],['all',tr('active')],['archive',tr('paidArchive')]],poFilter),'onchange="poFilter=this.value;selectedIds.clear();render()"')}<span class="pill">${fmt(pos.length)} POs</span></div>`;
  const byPO=new Map();for(const r of data.regional_rows||[]){if(!byPO.has(r.po_number))byPO.set(r.po_number,[]);byPO.get(r.po_number).push(r)}
  const cards=pos.map(x=>{let regional=byPO.get(x.number)||[],lines=(data.lines||[]).filter(l=>l.po_number===x.number),parts=regional.length?regional.map(r=>[r.item_text,Number(String(r.left_qty||'').replaceAll(',',''))>0?r.left_qty:r.planned_qty,r.due_date]):lines.map(l=>[l.item_code,l.quantity,l.due_date]);let assigned=(data.assigned_invoice_numbers||[]).find(n=>n.po_id===x.id)?.number;return `<article class="po-row ${x.urgent?'po-urgent':''}"><label class="po-check"><input type="checkbox" ${selectedIds.has(x.id)?'checked':''} onchange="togglePOSelection(${x.id},this.checked)"><span class="sr-only">Select ${esc(x.number)}</span></label><div class="po-main"><button class="po-link" onclick="openPO(${x.id})">${esc(x.number)}</button><div class="po-meta">${esc(x.region||'—')} · ${esc(x.address||x.customer||'—')}</div><div class="po-tags">${x.urgent?'<span class="pill danger">🚨 Overdue</span>':''}<span class="pill">${st(x.status)}</span>${assigned?`<span class="pill">${esc(assigned)}</span>`:''}</div></div><div class="po-items">${parts.slice(0,2).map(([code,quantity,due])=>`<div><strong>${esc(code||'—')}</strong><span>${esc(quantity||'—')} pcs · ${esc(String(due||'—').slice(0,10))}</span></div>`).join('')}${parts.length>2?`<small>+${parts.length-2} more schedules in Details</small>`:''}</div><div class="po-actions"><button class="primary" onclick="openPO(${x.id})">${tr('details')}</button></div></article>`}).join('');
  const assignment=user?.is_admin&&poFilter==='outstanding'?`<div class="card compact"><h3>Assign selected POs</h3><div class="assignment-form"><span class="pill"><span id="selection-count">${selectedIds.size}</span> ${tr('selected')}</span><form class="assignment-form" onsubmit="assignASN(event)">${select('assigned_to',tr('assignTo'),choices([['','Select user'],...users.filter(x=>x.active&&!x.is_admin).map(x=>[x.username,x.username])]),'required')}${field('due_date',tr('due'),'date','required')}<button class="primary">${tr('assignASN')}</button></form><form class="assignment-form" onsubmit="assignWarehouse(event)">${select('assigned_to','Warehouse user',choices([['','Select user'],...users.filter(x=>x.active&&!x.is_admin).map(x=>[x.username,x.username])]),'required')}${field('due_date',tr('due'),'date','required')}<button class="secondary">Assign dispatch</button></form></div></div>`:'';
  shell(filters+assignment+`<div class="po-list">${cards||`<div class="card empty">${tr('noRows')}</div>`}</div>`,tr('outstandingPOs'),'Select a PO to see its complete record and files.');
}
async function assignWarehouse(e){e.preventDefault();if(!selectedIds.size)return toast('Select at least one PO');let f=e.target;if(!confirm(`Assign ${selectedIds.size} POs to warehouse?`))return;try{await api('warehouse-assignments','POST',{po_ids:[...selectedIds],assigned_to:f.assigned_to.value,due_date:f.due_date.value});selectedIds.clear();await refresh();toast('Warehouse assignments created')}catch(x){toast(x.message)}}
