async function addItem(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.pcs_per_box=Number(x.pcs_per_box);x.boxes_per_pallet=Number(x.boxes_per_pallet);try{await api('items','POST',x);await refresh()}catch(y){toast(y.message)}}async function receiveBatch(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.quantity=Number(x.quantity);try{await api('batches','POST',x);await refresh()}catch(y){toast(y.message)}}async function returnStock(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));if(!confirm(tr('confirm')+'?'))return;try{await api(`invoices/${x.invoice_id}/returns`,'POST',{batch_id:Number(x.batch_id),quantity:Number(x.quantity),confirmed:true});await refresh()}catch(y){toast(y.message)}}async function previewStock(e){e.preventDefault();let file=e.target.file.files[0],fd=new FormData();fd.set('file',file);try{let j=await api('inventory/starting-preview','POST',fd);previewState={kind:'stock',file,fingerprint:j.fingerprint};document.getElementById('stock-preview').innerHTML=previewPanel(j,'applyStock()')}catch(x){toast(x.message)}}async function applyStock(){if(!previewState||previewState.kind!=='stock'||!confirm(tr('confirm')+'?'))return;let fd=new FormData();fd.set('file',previewState.file);fd.set('fingerprint',previewState.fingerprint);try{let j=await api('inventory/starting-apply','POST',fd);await refresh();toast(`${j.rows} rows imported`)}catch(x){toast(x.message)}}
function reportView(){let metrics=report.metrics||{},cards=`<div class="stats stats-five">${[["All PO value",metrics.all_po_value],["Outstanding value (estimated)",metrics.outstanding_value],["Paid (SAR)",metrics.paid_value],["Marketplace",metrics.marketplace_value],["Tender",metrics.tender_value],["Uploaded, unpaid",metrics.uploaded_unpaid_value]].map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${money(value)}</strong></div>`).join('')}</div>`;let regions=ops.regions||[],choice=choices([['',tr('allRegions')],...regions.map(r=>[r,r])],regionFilter),byRegion=(ops.by_region_item||[]).filter(x=>!regionFilter||x.region===regionFilter),pick=(ops.warehouse_pick_list||[]).filter(x=>!regionFilter||x.region===regionFilter);shell(cards+`<div class="card"><div class="split">${select('region',tr('region'),choice,'onchange="regionFilter=this.value;render()"')}<a class="button secondary" href="/api/export/masterlist.xlsx">Export PO masterlist</a><button class="secondary" onclick="exportPickList()">${tr('exportCSV')} · ${tr('warehouse')}</button><button class="secondary" onclick="exportReport('item')">${tr('exportCSV')} · ${tr('byItem')}</button><button class="secondary" onclick="exportReport('region')">${tr('exportCSV')} · ${tr('byRegionItem')}</button></div></div><div class="grid"><div class="card"><h3>${tr('byItem')}</h3><p class="hint">${tr('reportHelp')}</p>${table([tr('item'),tr('quantity')],(ops.by_item||[]).map(x=>`<tr><td class="code">${esc(x.item_code)}</td><td>${fmt(x.quantity)}</td></tr>`))}</div><div class="card"><h3>${tr('byRegionItem')}</h3>${table([tr('region'),tr('item'),tr('quantity')],byRegion.map(x=>`<tr><td>${esc(x.region)}</td><td class="code">${esc(x.item_code)}</td><td>${fmt(x.quantity)}</td></tr>`))}</div></div><div class="card"><h3>${tr('warehouse')}</h3>${table([tr('po'),tr('item'),tr('quantity'),tr('batch'),tr('boxes'),tr('pallets'),tr('address')],pick.map(x=>`<tr><td class="code">${esc(x.number)}</td><td>${esc(x.item_code)}</td><td>${fmt(x.outstanding_qty)}</td><td>${esc((x.batches||[]).map(b=>`${b.batch_no} (${b.quantity}, ${b.source})`).join(', '))}</td><td>${fmt(x.boxes)}</td><td>${fmt(x.pallets)}</td><td>${esc(x.address)}</td></tr>`))}</div><div class="grid"><div class="card"><h3>PO values by region</h3>${table([tr('region'),'POs',tr('value')],(report.by_region||[]).map(x=>`<tr><td>${esc(x.region)}</td><td>${fmt(x.po_count)}</td><td>${money(x.value)}</td></tr>`))}</div><div class="card"><h3>Invoice pipeline</h3>${table([tr('status'),tr('invoice'),tr('value')],(report.invoice_status||[]).map(x=>`<tr><td>${st(x.status)}</td><td>${fmt(x.count)}</td><td>${money(x.value)}</td></tr>`))}</div></div>`,tr('reports'))}
function exportReport(kind){let rows=kind==='item'?(ops.by_item||[]):(ops.by_region_item||[]).filter(x=>!regionFilter||x.region===regionFilter),keys=kind==='item'?['item_code','quantity']:['region','item_code','quantity'];downloadCSV(kind==='item'?'outstanding-by-item.csv':'outstanding-by-region-item.csv',rows,keys)}function downloadCSV(name,rows,keys){let csv=[keys.join(','),...rows.map(x=>keys.map(k=>'"'+String(x[k]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}function exportPickList(){let rows=(ops.warehouse_pick_list||[]).filter(x=>!regionFilter||x.region===regionFilter),keys=['number','region','item_code','outstanding_qty','boxes','pallets','address'];let csv=[keys.join(','),...rows.map(x=>keys.map(k=>'"'+String(x[k]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='warehouse-pick-list.csv';a.click();URL.revokeObjectURL(a.href)}
function previewPanel(j,action){return `<div class="alert ${j.ready?'':'danger'}">${fmt(j.rows||j.files?.length||0)} ${j.files?'files':'rows'} · ${fmt(j.error_count||0)} errors ${j.distinct_pos!==undefined?' · '+fmt(j.distinct_pos)+' POs':''}</div>${j.errors?.length?`<pre class="preview">${esc(JSON.stringify(j.errors,null,2))}</pre>`:''}${j.ready?`<button class="primary" onclick="${action}">${tr('approveAll')}</button>`:''}`}
function importsView(){let types=[['masterlist','PO Masterlist'],['due_region','Due and Region'],['sial_formatted','Sial PO Report (latest)']];shell(`<div class="card"><h3>${tr('uploadPO')}</h3><p class="hint">${tr('pdfHelp')}</p><form class="form" onsubmit="previewPDFs(event)"><label class="file-input full">${tr('chooseFiles')}<input type="file" name="files" accept=".pdf" multiple required></label><button class="primary">${tr('preview')}</button></form><div id="pdf-preview"></div></div><div class="grid"><div class="card"><h3>${tr('mergePDF')}</h3><form class="form one" onsubmit="mergePDFs(event)"><label class="file-input">PDF<input type="file" name="files" accept=".pdf" multiple required></label><button class="secondary">${tr('mergePDF')}</button></form></div><div class="card"><h3>${tr('importWorkbook')}</h3><p class="hint">${tr('importHelp')}</p><form class="form one" onsubmit="previewSeed(event)">${select('kind',tr('workbookType'),choices(types))}<label class="file-input">XLSX<input type="file" name="file" accept=".xlsx" required></label><button class="primary">${tr('preview')}</button></form><div id="seed-preview"></div></div></div><div class="card"><h3>${tr('softCopies')}</h3><p class="hint">${tr('softCopyHelp')}</p><form class="form" onsubmit="previewSoftCopies(event)"><label class="file-input full">PDF<input type="file" name="files" accept=".pdf" multiple required></label><button class="primary">${tr('preview')}</button></form><div id="soft-copy-preview"></div></div>`,tr('imports'))}
async function previewPDFs(e){e.preventDefault();let files=[...e.target.files.files],fd=new FormData();for(let f of files)fd.append('files',f);try{let j=await api('po-pdf/bulk-preview','POST',fd);previewState={kind:'pdf',files,fingerprints:j.files.map(x=>x.fingerprint)};document.getElementById('pdf-preview').innerHTML=j.files.map(x=>`<div class="card"><h3>${esc(x.filename)} · ${esc(x.po_number||'Unknown PO')}</h3><p class="small">${tr('value')}: ${money(x.value)} · ${x.po_number?.startsWith('300')&&x.customer_po?'Customer PO: '+esc(x.customer_po)+' · ':''}${esc(x.customer||'')} · Created: ${esc(x.created_at||'—')}</p>${x.error?`<div class="alert danger">${esc(x.error)}</div>`:''}${(x.warnings||[]).map(y=>`<div class="alert danger">${esc(y)}</div>`).join('')}${table(['#',tr('item'),tr('quantity'),tr('due'),tr('address')],(x.items||[]).map(item=>`<tr><td>${esc(item.line_no)}</td><td>${esc(item.item_code)}</td><td>${fmt(item.quantity)}</td><td>${esc(item.schedules.map(s=>s.due_date).join(', '))}</td><td>${esc(item.address)}</td></tr>`))}</div>`).join('')+(j.ready?`<button class="primary" onclick="approvePDFs()">${tr('approveAll')}</button>`:`<p class="alert danger">${tr('pdfWarning')}</p>`)}catch(x){toast(x.message)}}async function approvePDFs(){if(previewState?.kind!=='pdf'||!confirm(tr('confirm')+'?'))return;let fd=new FormData();for(let f of previewState.files)fd.append('files',f);fd.set('fingerprints',JSON.stringify(previewState.fingerprints));try{let j=await api('po-pdf/bulk-approve','POST',fd);previewState=null;regionFilter='';poFilter='outstanding';view='open';await refresh();toast(`${j.po_count} POs · ${j.documents_added} PDFs · ${j.duplicates_skipped} duplicates skipped`)}catch(x){toast(x.message)}}async function mergePDFs(e){e.preventDefault();let fd=new FormData();for(let f of e.target.files.files)fd.append('files',f);try{let r=await fetch('/api/po-pdf/merge',{method:'POST',headers:{'X-Logistics-Request':'1'},body:fd});if(!r.ok){let j=await r.json();throw Error(detailError(j))}let blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='merged-po-documents.pdf';a.click();URL.revokeObjectURL(a.href)}catch(x){toast(x.message)}}async function previewSeed(e){e.preventDefault();let kind=e.target.kind.value,file=e.target.file.files[0],fd=new FormData();fd.set('file',file);try{let j=await api(`seed/${kind}/preview`,'POST',fd);previewState={kind:'seed',seedKind:kind,file,fingerprint:j.fingerprint};document.getElementById('seed-preview').innerHTML=previewPanel(j,'applySeed()')}catch(x){toast(x.message)}}async function applySeed(){if(previewState?.kind!=='seed'||!confirm(tr('confirm')+'?'))return;let fd=new FormData();fd.set('file',previewState.file);fd.set('fingerprint',previewState.fingerprint);try{let j=await api(`seed/${previewState.seedKind}/apply`,'POST',fd);await refresh();toast(`${j.rows} rows imported`)}catch(x){toast(x.message)}}
async function previewSoftCopies(e){e.preventDefault();let files=[...e.target.files.files],fd=new FormData();for(let f of files)fd.append('files',f);try{let j=await api('po-documents/bulk-preview','POST',fd);previewState={kind:'soft',files,fingerprints:j.files.map(x=>x.fingerprint)};document.getElementById('soft-copy-preview').innerHTML=`<div class="alert">${j.known_count} matched · ${j.duplicates} duplicates</div>`+table(['PDF',tr('po'),tr('status')],j.files.map(x=>`<tr><td>${esc(x.filename)}</td><td>${esc(x.po_number||'—')}</td><td>${esc(x.error||(!x.known?'Unknown PO':x.duplicate?'Duplicate':'Ready'))}</td></tr>`))+(j.ready?`<button class="primary" onclick="attachSoftCopies()">${tr('approveAll')}</button>`:'')}catch(x){toast(x.message)}}
async function attachSoftCopies(){if(previewState?.kind!=='soft'||!confirm(tr('confirm')+'?'))return;let fd=new FormData();for(let f of previewState.files)fd.append('files',f);fd.set('fingerprints',JSON.stringify(previewState.fingerprints));try{let j=await api('po-documents/bulk-attach','POST',fd);previewState=null;await refresh();toast(`${j.documents_added} PDFs added · ${j.duplicates_skipped} duplicates skipped`)}catch(x){toast(x.message)}}
function tasksView(){
  const pos=data.pos||[],tasks=(data.tasks||[]).filter(x=>!['asn_booking','warehouse_dispatch'].includes(x.task_type));
  const asnRows=asnAssignments.map(x=>`<tr><td><button class="secondary" onclick="openPO(${x.po_id})">${esc(x.po_number)}</button></td><td>${esc(x.assigned_to)}</td><td>${esc(x.invoice_number)}</td><td>${esc(x.due_date||'—')}</td><td><span class="pill">${esc(x.status)}</span></td><td>${x.status==='submitted'&&user.is_admin?`<div class="actions"><button class="primary" onclick="reviewASN(${x.id},'accept')">${tr('accept')}</button><button class="secondary" onclick="reviewASN(${x.id},'return')">${tr('return')}</button></div>`:x.assigned_to===user.username&&['open','in_progress','returned'].includes(x.status)?`<button class="primary" onclick="document.getElementById('asn-${x.id}').hidden=false">${tr('submitASN')}</button>`:''}${x.status==='returned'?`<p class="hint">${esc(x.details||'')}</p>`:''}</td></tr><tr id="asn-${x.id}" hidden><td colspan="6"><form class="form" onsubmit="submitASN(event,${x.id})">${field('asn_number','ASN #','text',`value="${esc(x.asn_number||'')}"`)}${field('asn_date','ASN '+tr('date'),'date',`value="${esc(x.asn_date||'')}" required`)}${field('asn_link','ASN URL','url',`value="${esc(x.asn_link||'')}"`)}${field('planned_delivery_date','Planned delivery date','date','required')}${field('remarks',tr('reason'),'text',`value="${esc(x.asn_remarks||'')}"`)}<button class="primary">${tr('submitASN')}</button></form></td></tr>`);
  const asn=`<div class="card"><h3>${tr('asnTasks')}</h3>${table([tr('po'),tr('assignedTo'),tr('invoiceNumber'),tr('due'),tr('status'),''],asnRows)}</div>`;
  const assign=user.is_admin?`<div class="card"><h3>${tr('assignTask')}</h3><form class="form" onsubmit="createTask(event)">${field('title',tr('title'),'text','required')}${field('assigned_to',tr('assignedTo'),'text','required')}${select('po_id',tr('po'),choices([['','—'],...pos.map(p=>[p.id,p.number])]))}${field('due_date',tr('due'),'date')}${field('details',tr('details'))}<button class="primary">${tr('assignTask')}</button></form></div>`:'';
  const other=can('task_edit')?`<div class="card">${table([tr('title'),tr('assignedTo'),tr('po'),tr('due'),tr('status')],tasks.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.assigned_to)}</td><td>${esc(pos.find(p=>p.id===x.po_id)?.number)}</td><td>${esc(x.due_date)}</td><td>${select('status','',choices(['open','in_progress','done'].map(y=>[y,st(y)]),x.status),`onchange="taskStatus(${x.id},this.value)"`)}</td></tr>`))}</div>`:'';
  const warehouse=`<div class="card"><h3>Warehouse dispatch assignments</h3>${table([tr('po'),tr('invoice'), 'ASN',tr('item')+' / '+tr('quantity')+' / '+tr('batch'),tr('address'),tr('status'),''],warehouseAssignments.map(x=>`<tr><td><button class="secondary" onclick="openPO(${x.po_id})">${esc(x.po_number)}</button></td><td>${esc(x.invoice_number||'—')}</td><td>${esc(x.asn_number||'—')}</td><td>${esc((x.items||[]).map(i=>`${i.item_code}: ${i.booked_qty||i.quantity} pcs ${i.batch_no||''}`).join(' · '))}</td><td>${esc(x.address_ar||x.address||'—')}</td><td>${st(x.status)}</td><td>${x.status==='open'&&(!user.is_admin)?`<div class="actions"><button class="primary" onclick="warehouseUpdate(${x.id},'dispatched')">Dispatched</button><button class="secondary" onclick="warehouseUpdate(${x.id},'dispatch_cancelled')">Dispatch Cancelled</button></div>`:''}</td></tr>`))}</div>`;
  shell(asn+warehouse+assign+other,tr('tasks'));
}
async function warehouseUpdate(id,status){let reason='';if(status==='dispatch_cancelled'){reason=prompt('Why was dispatch cancelled?')||'';if(!reason)return}if(!confirm(`${st(status)}?`))return;try{await api(`warehouse-assignments/${id}/status`,'POST',{status,reason});await refresh();toast(st(status))}catch(x){toast(x.message)}}
async function submitASN(e,id){e.preventDefault();try{await api(`asn-assignments/${id}/submit`,'POST',Object.fromEntries(new FormData(e.target)));await refresh();toast(tr('submitASN'))}catch(x){toast(x.message)}}
async function reviewASN(id,action){let reason='';if(action==='return'){reason=prompt(tr('reason'))||'';if(!reason)return}if(!confirm(`${tr('confirm')}: ${tr(action)}?`))return;try{await api(`asn-assignments/${id}/review`,'POST',{action,reason});await refresh();toast(tr(action))}catch(x){toast(x.message)}}
async function createTask(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.po_id=x.po_id?Number(x.po_id):null;try{await api('tasks','POST',x);await refresh()}catch(y){toast(y.message)}}async function taskStatus(id,status){try{await api(`tasks/${id}`,'PATCH',{status});await refresh()}catch(x){toast(x.message)}}
function adminView(){if(!user?.is_admin){shell(`<div class="card"><form class="form" onsubmit="changePassword(event)">${field('old_password',tr('currentPassword'),'password','required')}${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('changePassword')}</button></form></div>`,tr('admin'));return}let perms=['merge_pdfs','accounting_edit','pos_edit','inventory_edit','invoice_edit','issue_edit','task_edit','reports_view','imports_apply','users_manage'];shell(`<div class="grid"><div class="card"><h3>${tr('createUser')}</h3><form class="form" onsubmit="createUser(event)">${field('username',tr('user'),'text','required')}${field('password',tr('password'),'password','minlength="12" required')}${field('email','Email','email')}${select('role','Role',choices([['staff','Staff'],['warehouse','Warehouse'],['accountant','Accountant']]))}<label class="check"><input name="is_admin" type="checkbox">${tr('assistantAdmin')}</label><div class="full">${perms.map(p=>`<label class="check"><input type="checkbox" name="permission" value="${p}">${esc(p.replaceAll('_',' '))}</label>`).join('')}</div><button class="primary">${tr('createUser')}</button></form></div><div class="card"><h3>${tr('users')}</h3><div id="user-list"></div><button class="secondary" onclick="loadUsers()">Refresh</button></div></div><div class="grid"><div class="card"><h3>${tr('customStatuses')}</h3><p class="hint">Core workflow statuses must remain in the list. Add custom codes separated by commas.</p><form class="form one" onsubmit="saveStatuses(event)">${select('group',tr('status'),choices([['po',tr('status')],['invoice',tr('invoiceStage')]]),'onchange="document.querySelector(\'[name=options]\').value=statusOptions[this.value].join(\', \')"')}<label>Codes<textarea name="options">${esc((statusOptions.po||[]).join(', '))}</textarea></label><button class="primary">${tr('save')}</button></form></div><div class="card"><h3>${tr('changePassword')}</h3><form class="form" onsubmit="changePassword(event)">${field('old_password',tr('currentPassword'),'password','required')}${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('changePassword')}</button></form></div></div><div class="card"><h3>${tr('undoImports')}</h3><p class="hint">A backup is created before each import. Reset removes every PO and its linked work history, while preserving users and physical stock.</p><div class="actions"><button class="secondary" onclick="loadBackups()">${tr('backup')}</button><button class="danger" onclick="resetAllPOs()">${tr('resetPOs')}</button><button class="danger" onclick="deleteBackups(false)">Delete selected backups</button><button class="danger" onclick="deleteBackups(true)">Delete all backups</button></div><div id="backup-list"></div></div>`,tr('admin'));loadUsers();loadBackups()}
async function loadBackups(){try{let b=await api('admin/backups');backups=b.backups||b;let node=document.getElementById('backup-list');if(node)node.innerHTML=table([tr('date'),tr('details'),''],backups.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.label)}</td><td><input type="checkbox" class="backup-check" value="${esc(x.id)}"><a class="button secondary" href="/api/admin/backups/${esc(x.id)}">${tr('download')}</a> <button class="secondary" onclick="restoreBackup('${esc(x.id)}')">${tr('restore')}</button></td></tr>`))}catch(x){toast(x.message)}}
async function resetAllPOs(){try{let preview=await api('admin/reset-preview');let phrase=prompt(`This deletes ${preview.pos} POs, ${preview.invoices} invoices, ${preview.linked_tasks} linked tasks and all PO history. A backup is saved first. Type RESET ALL PURCHASE ORDERS to continue.`);if(phrase!=='RESET ALL PURCHASE ORDERS')return;let j=await api('admin/reset-pos','POST',{phrase});selectedPO=null;selectedIds.clear();await refresh();toast(`PO reset complete. Backup ${j.backup_id}`)}catch(x){toast(x.message)}}
async function restoreBackup(backup_id){let phrase=prompt(`Restore backup ${backup_id}? Current data will be saved first. Type RESTORE DATABASE to continue.`);if(phrase!=='RESTORE DATABASE')return;try{await api('admin/restore-backup','POST',{backup_id,phrase});await refresh();toast(tr('restore'))}catch(x){toast(x.message)}}
async function changePassword(e){e.preventDefault();try{await api('auth/password','POST',Object.fromEntries(new FormData(e.target)));user=null;loginView();toast(tr('signIn'))}catch(x){toast(x.message)}}async function createUser(e){e.preventDefault();let f=e.target,body={username:f.username.value,password:f.password.value,email:f.email.value,role:f.role.value,is_admin:f.is_admin.checked,permissions:[...f.querySelectorAll('[name=permission]:checked')].map(x=>x.value)};try{await api('auth/users','POST',body);await loadUsers();f.reset();toast(tr('save'))}catch(x){toast(x.message)}}async function loadUsers(){try{users=await api('auth/users');let node=document.getElementById('user-list');if(!node)return;node.innerHTML=`<div class="user-cards">${users.map(x=>`<section class="user-card"><div class="user-card-head"><div><strong>${esc(x.username)}</strong><small>${esc(x.username==='admin'?'Main admin':x.is_admin?tr('assistantAdmin'):x.role||'Staff')} · ${x.active?'Active':'Inactive'}</small></div></div><div class="actions"><button class="secondary" onclick="editUser(${x.id})">Edit access</button>${x.username==='admin'?'':`<button class="danger" onclick="deleteUser(${x.id})">Delete</button>`}</div><details class="reset-user"><summary>Reset password</summary><form onsubmit="resetUserPassword(event,${x.id})"><label>New password<input name="password" type="password" minlength="12" autocomplete="new-password" required></label><button class="secondary">Save new password</button></form></details></section>`).join('')}</div>`}catch(x){toast(x.message)}}
async function editUser(id){let x=users.find(y=>y.id===id);if(!x)return;let p=prompt('Permissions, comma separated',x.permissions);if(p===null)return;let role=prompt('Role: staff, warehouse, or accountant',x.role||'staff');if(role===null)return;let active=confirm(x.active?'Keep this account active? Cancel will deactivate it.':'Activate this account?');try{await api(`auth/users/${id}`,'PATCH',{permissions:p.split(',').map(z=>z.trim()).filter(Boolean),active,role});await loadUsers();toast(tr('save'))}catch(y){toast(y.message)}}
async function resetUserPassword(e,id){e.preventDefault();let form=e.target,password=form.elements.password.value;if(!password)return;try{await api(`auth/users/${id}`,'PATCH',{password});form.reset();toast('Password reset');await loadUsers()}catch(err){toast(err.message)}}
async function deleteUser(id){if(!confirm('Delete this account? Assigned work will be unassigned and history retained.'))return;try{await api(`auth/users/${id}`,'DELETE');await loadUsers();toast('Account deleted')}catch(e){toast(e.message)}}
async function saveStatuses(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));try{await api('status-options','PUT',{group:x.group,options:x.options.split(',').map(y=>y.trim())});statusOptions=await api('status-options');render();toast(tr('save'))}catch(y){toast(y.message)}}
if(new URLSearchParams(location.search).has('reset')){let token=new URLSearchParams(location.search).get('reset');document.getElementById('app').innerHTML=`<div class="login card"><h3>${tr('newPassword')}</h3><form onsubmit="finishReset(event)">${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('save')}</button></form></div>`;window.finishReset=async e=>{e.preventDefault();try{await api('auth/reset-confirm','POST',{token,new_password:e.target.new_password.value});history.replaceState(null,'','/');loginView();toast(tr('signIn'))}catch(x){toast(x.message)}}}else refresh();

async function deleteBackups(all=false){let ids=all?['*']:[...document.querySelectorAll('.backup-check:checked')].map(x=>x.value);if(!ids.length)return toast('Select backups');if(!confirm('Permanently delete '+(all?'ALL backups':ids.length+' selected backups')+'?'))return;try{await api('admin/backups/delete','POST',{ids,phrase:'DELETE SELECTED BACKUPS'});await loadBackups();toast('Backups deleted')}catch(e){toast(e.message)}}

async function savePayment(e,id){e.preventDefault();let f=e.target,x=Object.fromEntries(new FormData(f));x.amount_sar=Number(x.amount_sar);if(!confirm('Record payment of SAR '+x.amount_sar+'?'))return;try{await api(`pos/${id}/payment`,'POST',x);await refresh();toast('Payment saved')}catch(e){toast(e.message)}}async function rescheduleLine(e,id){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));if(!confirm('Reschedule due date?'))return;try{await api(`po-lines/${id}/reschedule`,'POST',x);await refresh();toast('Due date updated')}catch(e){toast(e.message)}}

async function mergeInvoicePackage(id){if(!confirm('Merge the required PO and invoice documents?'))return;try{let x=await api(`pos/${id}/documents/merge`,'POST',{});await refresh();toast(x.filename+' ready')}catch(e){toast(e.message)}}
